using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
    }

    [TestMethod]
    [DynamicData(nameof(GetScenarios), DynamicDataSourceType.Method)]
    public async Task EvaluateScenario(string scenarioName)
    {
        var config = EvaluationConfig.Load("evaluation.yml");
        var scenario = config.Scenarios.First(s => s.Name == scenarioName);

        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>();
        ChatResponse? response = null;

        foreach (var turn in scenario.Turns)
        {
            messages.Add(new ChatMessage(ChatRole.User, turn.Content));
            response = await chatClient.GetResponseAsync(messages);
            messages.Add(response.Message);
        }

        Assert.IsNotNull(response, "No response received from the chat client.");

        var evaluators = CreateEvaluators(scenario);
        var reportingConfig = new ReportingConfiguration(evaluators);

        await using var report = await reportingConfig.CreateReportAsync();
        var evalRun = await report.CreateScenarioRunAsync(scenarioName);

        await evalRun.EvaluateAsync(messages, response, additionalContext: []);

        foreach (var expectation in scenario.Expectations)
        {
            var result = evalRun.GetNumericMetric(expectation.Metric);
            Assert.IsTrue(
                result.Value >= expectation.Threshold,
                $"Scenario '{scenarioName}': Metric '{expectation.Metric}' scored {result.Value}, " +
                $"expected >= {expectation.Threshold}.");
        }
    }

    private static IEnumerable<object[]> GetScenarios()
    {
        var config = EvaluationConfig.Load("evaluation.yml");
        return config.Scenarios.Select(s => new object[] { s.Name });
    }

    private static IList<IEvaluator> CreateEvaluators(ScenarioConfig scenario)
    {
        var evaluators = new List<IEvaluator>();
        var metrics = scenario.Expectations.Select(e => e.Metric).Distinct();

        foreach (var metric in metrics)
        {
            switch (metric.ToLowerInvariant())
            {
                case "relevance":
                    evaluators.Add(new RelevanceEvaluator());
                    break;
                case "coherence":
                    evaluators.Add(new CoherenceEvaluator());
                    break;
                case "groundedness":
                    evaluators.Add(new GroundednessEvaluator());
                    break;
            }
        }

        return evaluators;
    }
}

